#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <gzip_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);

    unsigned char *inbuf = malloc(fsize);
    fread(inbuf, 1, fsize, f);
    fclose(f);

    z_stream strm;
    memset(&strm, 0, sizeof(strm));

    int ret = inflateInit2(&strm, MAX_WBITS + 32);
    if (ret != Z_OK) {
        fprintf(stderr, "inflateInit2 failed: %d\n", ret);
        return 1;
    }

    strm.next_in = inbuf;
    strm.avail_in = fsize;

    // Use a heap buffer of 512 bytes
    unsigned char *outbuf = malloc(512);
    memset(outbuf, 0xAB, 512);

    strm.next_out = outbuf;
    strm.avail_out = 512;

    ret = inflate(&strm, Z_SYNC_FLUSH);
    printf("inflate returned: %d\n", ret);
    printf("avail_in: %u, avail_out: %u\n", strm.avail_in, strm.avail_out);
    printf("total_out: %lu\n", strm.total_out);
    printf("msg: %s\n", strm.msg ? strm.msg : "NULL");

    // Check for overflow - don't read past buffer, just check if inflate wrote past it
    // by looking at the avail_out value
    printf("Bytes written: %lu\n", strm.total_out);
    printf("Expected written: %u\n", 512 - strm.avail_out);

    // The overflow is detected by ASAN when we try to read past the buffer
    // But the WRITE happened during inflate
    // Let's check what's at offset 512 (should be 0xAB if not overwritten)
    // Actually, ASAN will catch this

    inflateEnd(&strm);
    free(inbuf);
    free(outbuf);
    return 0;
}
EOF
